@extends('layouts.store')
@section('title','অর্ডার সম্পন্ন করুন - '.($siteSettings['site_name']??'Trendy Deal BD'))
@section('content')@php $subtotal=collect($cart)->sum(fn($x)=>$x['price']*$x['quantity']); $in=(float)($siteSettings['shipping_inside_dhaka']??60); $out=(float)($siteSettings['shipping_outside_dhaka']??120); @endphp<div class="checkout-bg"><section class="checkout-card"><div class="checkout-head"><h1>অর্ডার করতে আপনার তথ্য দিন</h1><a href="{{ route('cart') }}">×</a></div><form action="{{ route('checkout.store') }}" method="post" id="checkoutForm">@csrf<input type="hidden" name="event_id" id="purchaseEventId"><div class="form-icon-row"><span>👤</span><input name="customer_name" value="{{ old('customer_name') }}" placeholder="আপনার নাম" required></div><div class="form-icon-row"><span>☎</span><input name="phone" value="{{ old('phone') }}" placeholder="আপনার ফোন নম্বর" required></div><div class="form-icon-row"><span>⌖</span><textarea name="address" placeholder="আপনার সম্পূর্ণ ঠিকানা" required>{{ old('address') }}</textarea></div><div class="form-icon-row"><span>✉</span><input name="email" type="email" value="{{ old('email') }}" placeholder="ইমেইল (ঐচ্ছিক)"></div><h3>আপনার কার্ট</h3><div class="checkout-lines">@foreach($cart as $line)<div><span>{{ $line['name'] }} × {{ $line['quantity'] }}</span><b>৳{{ number_format($line['price']*$line['quantity'],2) }}</b></div>@endforeach</div><div class="totals"><div><span>সাবটোটাল</span><span>৳{{ number_format($subtotal,2) }}</span></div><div><span>ডেলিভারি</span><span id="shippingAmount">৳{{ number_format($in,2) }}</span></div><div class="grand"><span>মোট</span><strong id="grandTotal">৳{{ number_format($subtotal+$in,2) }}</strong></div></div><h3>ডেলিভারি এলাকা</h3><label class="shipping-choice"><input type="radio" name="shipping_area" value="inside" checked data-charge="{{ $in }}"> ঢাকা সিটির মধ্যে <b>৳{{ number_format($in,2) }}</b></label><label class="shipping-choice"><input type="radio" name="shipping_area" value="outside" data-charge="{{ $out }}"> ঢাকা সিটির বাইরে <b>৳{{ number_format($out,2) }}</b></label><textarea class="field" name="note" placeholder="অর্ডার নোট (ঐচ্ছিক)">{{ old('note') }}</textarea><button class="btn primary full checkout-submit">🛒 অর্ডার সম্পন্ন করুন - ৳<span id="buttonTotal">{{ number_format($subtotal+$in,0) }}</span></button></form></section></div>@endsection
@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const sub={{ $subtotal }};document.querySelectorAll('[name=shipping_area]').forEach(r=>r.addEventListener('change',()=>{const c=Number(document.querySelector('[name=shipping_area]:checked').dataset.charge);document.getElementById('shippingAmount').textContent='৳'+c.toFixed(2);document.getElementById('grandTotal').textContent='৳'+(sub+c).toFixed(2);document.getElementById('buttonTotal').textContent=(sub+c).toFixed(0)}));window.trackMeta?.('InitiateCheckout',{currency:'BDT',value:sub,content_type:'product'});document.getElementById('checkoutForm').addEventListener('submit',()=>{document.getElementById('purchaseEventId').value=window.metaEventId?.('purchase')||('purchase_'+Date.now())});});</script>@endpush
